/**
 * Cutout (sticker) library. README
 *
 * - One manifest module per category (./<category>.ts, GENERATED by scripts/stickers/build.mjs) exports
 *   `<CATEGORY>: StickerDef[]`. Manifests are loaded on demand with loadCategory(); nothing in this folder is
 *   imported eagerly, so the designer bundle does not grow. This file is cheap to import (labels and loaders only).
 * - `StickerDef.src` is a plain URL string built with `new URL('<relative svg path>', import.meta.url).href`.
 *   Vite turns that into a hashed asset URL (small SVGs under the inline limit become data URIs inside the lazy
 *   category chunk). Because the manifest is already lazy, `src` itself is a string, not a function: use it as an
 *   <img src> or Image().src directly. Each SVG has a viewBox and no width/height, so it scales to any size.
 * - kind 'colour': multi-colour artwork. 'mono': one colour on transparent (tint-friendly). 'pattern': a seamless
 *   square tile (single colour on transparent) meant to be repeated.
 * - Artwork credits (Fluent Emoji, Lucide) live in src/content/imageCredits.ts and are shown on /image-credits.
 * - To add or change items edit the catalogs in scripts/stickers and re-run:
 *     node scripts/stickers/build.mjs --fluent <dir with icons.json from @iconify-json/fluent-emoji-flat>
 */
import type { StickerDef } from '../types';
import type { CategoryId } from './types';

export type { CategoryId } from './types';

export interface StickerCategory {
  id: CategoryId;
  label: string;
  /** Display order, ascending */
  order: number;
}

export const CATEGORIES: readonly StickerCategory[] = [
  { id: 'fruits-veg', label: 'Fruits & vegetables', order: 1 },
  { id: 'bakery-food', label: 'Bakery & food', order: 2 },
  { id: 'drinks', label: 'Drinks', order: 3 },
  { id: 'clothing', label: 'Clothing & fashion', order: 4 },
  { id: 'footwear-accessories', label: 'Footwear & accessories', order: 5 },
  { id: 'beauty-wellness', label: 'Beauty & wellness', order: 6 },
  { id: 'electronics', label: 'Electronics', order: 7 },
  { id: 'gifts-festive', label: 'Gifts & festive', order: 8 },
  { id: 'home-kitchen', label: 'Home & kitchen', order: 9 },
  { id: 'flowers-plants', label: 'Flowers & plants', order: 10 },
  { id: 'animals-kids', label: 'Animals & kids', order: 11 },
  { id: 'shipping-marks', label: 'Shipping & handling marks', order: 12 },
  { id: 'badges-labels', label: 'Badges & labels', order: 13 },
  { id: 'shapes-frames', label: 'Shapes & frames', order: 14 },
  { id: 'patterns', label: 'Seamless patterns', order: 15 },
  { id: 'contact-icons', label: 'Contact icons', order: 16 },
];

const LOADERS: Record<CategoryId, () => Promise<StickerDef[]>> = {
  'fruits-veg': () => import('./fruits-veg').then((m) => m.FRUITS_VEG),
  'bakery-food': () => import('./bakery-food').then((m) => m.BAKERY_FOOD),
  'drinks': () => import('./drinks').then((m) => m.DRINKS),
  'clothing': () => import('./clothing').then((m) => m.CLOTHING),
  'footwear-accessories': () => import('./footwear-accessories').then((m) => m.FOOTWEAR_ACCESSORIES),
  'beauty-wellness': () => import('./beauty-wellness').then((m) => m.BEAUTY_WELLNESS),
  'electronics': () => import('./electronics').then((m) => m.ELECTRONICS),
  'gifts-festive': () => import('./gifts-festive').then((m) => m.GIFTS_FESTIVE),
  'home-kitchen': () => import('./home-kitchen').then((m) => m.HOME_KITCHEN),
  'flowers-plants': () => import('./flowers-plants').then((m) => m.FLOWERS_PLANTS),
  'animals-kids': () => import('./animals-kids').then((m) => m.ANIMALS_KIDS),
  'shipping-marks': () => import('./shipping-marks').then((m) => m.SHIPPING_MARKS),
  'badges-labels': () => import('./badges-labels').then((m) => m.BADGES_LABELS),
  'shapes-frames': () => import('./shapes-frames').then((m) => m.SHAPES_FRAMES),
  'patterns': () => import('./patterns').then((m) => m.PATTERNS),
  'contact-icons': () => import('./contact-icons').then((m) => m.CONTACT_ICONS),
};

const cache = new Map<CategoryId, Promise<StickerDef[]>>();

/** Lazily load one category manifest (cached). */
export function loadCategory(id: CategoryId): Promise<StickerDef[]> {
  let p = cache.get(id);
  if (!p) {
    p = LOADERS[id]();
    cache.set(id, p);
  }
  return p;
}

/** Load every category (for search across the whole library). Still lazy: call it on first search focus. */
export async function loadAllCategories(): Promise<StickerDef[]> {
  const lists = await Promise.all(CATEGORIES.map((c) => loadCategory(c.id)));
  return lists.flat();
}
